const $=sel=>root.querySelector(sel);
const BASE={dataSet:'OmniMetrics',dateDimension:'Period',aggregations:['brandName'],groupBys:[],filters:{customBrandName:[],customCategory:[],brandName:[],category:[],promotionStatus:[],currentBadges:[],labels:[],historyLabels:[]},columnGroupTypes:['Advertising','ChannelSales','Inventory','OnlineOrganicSales','OnlineSales','OverallSales','StoreSales'],isShowCompare:false,uniqueTimeZone:8};
const money=x=>x==null?'—':Number(x).toLocaleString('en-US',{maximumFractionDigits:2});
const el=(tag,cl,txt)=>{const n=document.createElement(tag);if(cl)n.className=cl;if(txt!=null)n.textContent=String(txt);return n};
function card(label,value){const d=el('div','card');d.append(el('span','',label),el('strong','',value));return d}
function paint(rows,hasNext){
 const cards=$('#cards');cards.replaceChildren();
 const sales=rows.reduce((s,r)=>s+(Number(r.adSalesAmount)||0),0);
 const spend=rows.reduce((s,r)=>s+(Number(r.adSpend)||0),0);
 cards.append(card('Ad Sales (page)',money(sales)),card('Ad Spend (page)',money(spend)),card('Weighted ROAS (page)',spend>0?(sales/spend).toFixed(2)+'x':'—'),card('Brands (page)',String(rows.length)));
 const barRoot=$('#bars');barRoot.replaceChildren();
 const entries=rows.map(r=>({name:r.brandName||'Unspecified',roas:Number(r.adSpend)>0?Number(r.adSalesAmount||0)/Number(r.adSpend):null}));
 const max=Math.max(1,...entries.map(x=>x.roas??0));
 for(const item of entries){const line=el('div','bar');const name=el('span','',item.name);name.title=item.name;const track=el('div','track');const fill=el('div','fill');fill.style.width=(item.roas==null?0:item.roas/max*100)+'%';track.append(fill);line.append(name,track,el('span','',item.roas==null?'—':item.roas.toFixed(2)+'x'));barRoot.append(line)}
 const table=el('table');const head=table.insertRow();for(const h of ['Brand','Ad Sales','Ad Spend','ROAS']){const th=el('th','',h);head.append(th)}
 for(const r of rows){const tr=table.insertRow();for(const v of [r.brandName||'Unspecified',money(r.adSalesAmount),money(r.adSpend),r.adRoas==null?'—':Number(r.adRoas).toFixed(2)+'x']){tr.append(el('td','',v))}}
 const scroll=el('div','scroll');scroll.append(table);$('#table').replaceChildren(scroll);
 $('#notice').textContent=hasNext?'More rows exist. Results and KPI cards show the first 100 returned rows only.':'All rows returned for this query page; check data completeness against Pacvue.';
}
async function run(){const start=$('#start').value,end=$('#end').value;if(!start||!end||start>end){$('#status').textContent='Please choose a valid date range.';return}
 const button=$('#run');button.disabled=true;$('#status').textContent='Loading…';
 try{const result=await reportAPI.queryTable({...BASE,startDate:start,endDate:end,pageNum:1,pageSize:100,orderBys:{orderBy:'adSalesAmount',orderType:'descending'}});
 const rows=Array.isArray(result?.list)?result.list:[];paint(rows,!!result?.hasNextPage);$('#status').textContent=rows.length?'Loaded '+rows.length+' brand rows':'No brands matched this date range.';
 }catch(e){$('#status').textContent='Query failed: '+e.message;$('#cards').replaceChildren();$('#bars').replaceChildren();$('#table').replaceChildren()}finally{button.disabled=false}}
$('#run').addEventListener('click',run);run();
